const recomputeSubcontractProgressClaimTotals = `-- name: RecomputeSubcontractProgressClaimTotals :one
UPDATE subcontract_progress_claims pc
SET gross_work_amount = sub.gross,
    retention_amount = round(sub.gross * pc.retention_percent_snapshot / 100, 2),
    previous_certified_amount = COALESCE(prev.amount, 0),
    current_certified_amount = COALESCE(prev.amount, 0) + sub.gross,
    net_payable = (sub.gross - round(sub.gross * pc.retention_percent_snapshot / 100, 2) - pc.advance_recovery_amount - pc.other_deductions)::numeric(18,2)
FROM (SELECT COALESCE(sum(current_progress_amount), 0)::numeric(18,2) AS gross
      FROM subcontract_progress_claim_items WHERE progress_claim_id = $1) sub,
     (SELECT (
          SELECT current_certified_amount FROM subcontract_progress_claims
          WHERE subcontract_id = (SELECT subcontract_id FROM subcontract_progress_claims WHERE id = $1)
            AND status = 'certified' AND id <> $1
          ORDER BY certified_at DESC LIMIT 1
      ) AS amount) prev
WHERE pc.id = $1 AND pc.organization_id = $2 AND pc.project_id = $3
RETURNING pc.id, pc.organization_id, pc.project_id, pc.subcontract_id, pc.claim_number, pc.period_start, pc.period_end, pc.status, pc.gross_work_amount, pc.retention_percent_snapshot, pc.retention_amount, pc.advance_recovery_amount, pc.other_deductions, pc.previous_certified_amount, pc.current_certified_amount, pc.net_payable, pc.submitted_at, pc.certified_at, pc.certified_by, pc.rejected_at, pc.rejected_by, pc.rejection_reason, pc.cancelled_at, pc.cancelled_by, pc.notes, pc.created_by, pc.created_at, pc.updated_at
`

type RecomputeSubcontractProgressClaimTotalsParams struct {
	ID             pgtype.UUID `json:"id"`
	OrganizationID pgtype.UUID `json:"organization_id"`
	ProjectID      pgtype.UUID `json:"project_id"`
}

// gross_work_amount kalemlerden; previous_certified_amount bu taşeronun
// ÖNCEKİ sertifikalı hakedişlerinin (bu hakediş HARİÇ) current_certified_
// amount'larının EN SONUNCUSU (kümülatif zincir); retention/net backend'de
// HER ZAMAN hesaplanır (spec §22, "double-count edilmemeli"). `prev`,
// HİÇBİR önceki sertifikalı hakediş yokken bile TEK bir satır döner
// (skaler alt sorgu, LIMIT 1'in kendisi FROM listesinde DEĞİL SELECT
// listesinde) -- aksi halde UPDATE...FROM'daki CROSS JOIN, 0 satırlı bir
// FROM kaynağı yüzünden HİÇBİR satırı güncellemez (ilk hakediş boş sonuç
// üretir).
func (q *Queries) RecomputeSubcontractProgressClaimTotals(ctx context.Context, arg RecomputeSubcontractProgressClaimTotalsParams) (SubcontractProgressClaim, error) {
	row := q.db.QueryRow(ctx, recomputeSubcontractProgressClaimTotals, arg.ID, arg.OrganizationID, arg.ProjectID)
	var i SubcontractProgressClaim
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.ProjectID,
		&i.SubcontractID,
		&i.ClaimNumber,
		&i.PeriodStart,
		&i.PeriodEnd,
		&i.Status,
		&i.GrossWorkAmount,
		&i.RetentionPercentSnapshot,
		&i.RetentionAmount,
		&i.AdvanceRecoveryAmount,
		&i.OtherDeductions,
		&i.PreviousCertifiedAmount,
		&i.CurrentCertifiedAmount,
		&i.NetPayable,
		&i.SubmittedAt,
		&i.CertifiedAt,
		&i.CertifiedBy,
		&i.RejectedAt,
		&i.RejectedBy,
		&i.RejectionReason,
		&i.CancelledAt,
		&i.CancelledBy,
		&i.Notes,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

